import { API_VERSION_PREFIX } from '06_shared/constants/api';
import { LS_ACCESS_TOKEN } from '06_shared/constants/localStorage';
import { sessionId, visitorId } from './visitorIds';
const UTM_KEYS = ['utm_source', 'utm_medium', 'utm_campaign'];
const UTM_MAX = 128;
const size = (width, height) => width > 0 && height > 0 ? `${Math.round(width)}x${Math.round(height)}` : undefined;
const timezone = () => {
    try {
        return Intl.DateTimeFormat().resolvedOptions().timeZone || undefined;
    }
    catch {
        return undefined;
    }
};
export const buildPageViewBody = (pathname, search) => {
    const session = sessionId();
    const body = {
        visitor_id: visitorId(),
        session_id: session.id,
        path: pathname || '/',
        language: navigator.language || undefined,
        timezone: timezone(),
        screen: size(window.screen.width, window.screen.height),
        viewport: size(window.innerWidth, window.innerHeight),
        webdriver: navigator.webdriver === true,
    };
    // Звідки прийшли — лише на першій сторінці візиту: далі referrer — це
    // вже наш сайт.
    if (session.created) {
        if (document.referrer)
            body.referrer = document.referrer.slice(0, 2048);
        const params = new URLSearchParams(search);
        UTM_KEYS.forEach((key) => {
            const value = params.get(key);
            if (value)
                body[key] = value.slice(0, UTM_MAX);
        });
    }
    return body;
};
// Відправка «вистрілив і забув»: лічильник ніколи не заважає сайту.
// keepalive — запит доходить, навіть якщо вкладку вже закривають.
export const sendPageView = (body) => {
    const headers = { 'Content-Type': 'application/json' };
    try {
        // Токен уже збережено разом зі схемою ("Bearer …", userApi.signIn) —
        // так само, як його шле baseQuery.
        const authorization = localStorage.getItem(LS_ACCESS_TOKEN);
        if (authorization)
            headers.Authorization = authorization;
    }
    catch {
        // без сховища — гостьовий хіт
    }
    try {
        fetch(`${__API_URL__}${API_VERSION_PREFIX}/public/page-views`, {
            method: 'POST',
            headers,
            body: JSON.stringify(body),
            keepalive: true,
        }).catch(() => undefined);
    }
    catch {
        // fetch недоступний — хіт не рахується
    }
};
