// Значення — ключі перекладу (основний простір translation).
export const NEURON_SIGNAL_MODE_SHORT = {
    relative: 'REL',
    legacy: 'LEG',
};
// Ключі перекладу попередження: трейдер у relative, а нейрон без шкали.
export const NO_SCALE_WARNING = 'No trades will open: the current neuron has no scale'
    + ' — switch to Legacy or wait for a new neuron.';
// Шкали напрямку є, а шкал руху по сторонах немає — нейрон відкалібровано
// старою версією (до v5): його треба перекалібрувати.
export const NO_MOVE_SCALE_WARNING = 'No trades will open: the current neuron has no'
    + ' move scale (calibrated before v5) — recalibrate it or switch to Legacy.';
export const NEURON_SIGNAL_MODE_LABEL = {
    relative: 'Relative',
    legacy: 'Legacy',
};
// Частки шкали 0..1 -> «22.0%→59.0%».
export const formatNeuronScale = (scale) => (`${(scale.base * 100).toFixed(1)}%→${(scale.max * 100).toFixed(1)}%`);
// Відносні пороги сторони можна порівняти лише з обома її шкалами (рух і
// напрямок). Без жодної такої сторони в режимі relative угода не відкриється.
export const hasNeuronScale = (neuron) => (neuron.neuron_has_scale
    && ((neuron.move_buy_scale != null && neuron.direction_buy_scale != null)
        || (neuron.move_sell_scale != null && neuron.direction_sell_scale != null)));
// Зразок для заглушок рядка нейрона: той самий текст із типовими числами,
// тож заглушка переноситься на стільки ж рядків, як справжній рядок.
const SAMPLE_SCALE = { base: 0.5, max: 0.55 };
export const CURRENT_NEURON_SAMPLE = {
    neuron_uuid: 'sample',
    neuron_tag_name: 'neuron',
    neuron_signal_mode: 'relative',
    move_buy_scale: SAMPLE_SCALE,
    move_sell_scale: SAMPLE_SCALE,
    direction_buy_scale: SAMPLE_SCALE,
    direction_sell_scale: SAMPLE_SCALE,
};
// «Поточний нейрон: тег · режим · шкала: лонг: рух base→max, напрямок
// base→max; шорт: …».
export const describeNeuron = (t, neuron) => {
    const sideScales = (side, move, direction) => {
        const scales = [
            move && `${t('move')} ${formatNeuronScale(move)}`,
            direction && `${t('direction')} ${formatNeuronScale(direction)}`,
        ].filter(Boolean);
        return scales.length ? `${t(side)}: ${scales.join(', ')}` : null;
    };
    const scaleParts = [
        sideScales('long', neuron.move_buy_scale, neuron.direction_buy_scale),
        sideScales('short', neuron.move_sell_scale, neuron.direction_sell_scale),
    ].filter(Boolean);
    const parts = [
        neuron.neuron_tag_name || neuron.neuron_uuid.split('-')[0],
        t(NEURON_SIGNAL_MODE_LABEL[neuron.neuron_signal_mode]),
        `${t('scale')}: ${scaleParts.length ? scaleParts.join('; ') : t('none')}`,
    ];
    return `${t('Current neuron')}: ${parts.join(' · ')}`;
};
// Яке попередження показати трейдеру в relative, коли шкали не вистачає.
export const noScaleWarning = (neuron) => ((neuron.direction_buy_scale != null || neuron.direction_sell_scale != null)
    && neuron.move_buy_scale == null
    && neuron.move_sell_scale == null
    ? NO_MOVE_SCALE_WARNING
    : NO_SCALE_WARNING);
