import { generateUUID } from '06_shared/utils/generateUUID';
// Лічильник відвідувань (бекенд: domain.site_visit). Ідентифікатори — не
// персональні дані: випадкові UUID, щоб відрізнити одного відвідувача
// (браузер, localStorage) і один візит (вкладка, sessionStorage).
export const LS_VISITOR_ID = 'maia_visitor_id';
export const SS_SESSION_ID = 'maia_session_id';
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const newId = () => typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
    ? crypto.randomUUID()
    : generateUUID();
// Сховище може бути недоступне (приватний режим, заборонені cookies):
// тоді ідентифікатор живе лише в пам'яті сторінки.
const memory = {};
const readOrCreate = (storage, key) => {
    try {
        const stored = storage().getItem(key);
        if (stored && UUID_RE.test(stored))
            return { id: stored, created: false };
        const id = newId();
        storage().setItem(key, id);
        return { id, created: true };
    }
    catch {
        if (memory[key])
            return { id: memory[key], created: false };
        memory[key] = newId();
        return { id: memory[key], created: true };
    }
};
export const visitorId = () => readOrCreate(() => window.localStorage, LS_VISITOR_ID).id;
// created = перша сторінка цього візиту: лише вона несе referrer і utm.
export const sessionId = () => readOrCreate(() => window.sessionStorage, SS_SESSION_ID);
export const resetVisitorIdsForTests = () => {
    Object.keys(memory).forEach((key) => delete memory[key]);
};
